import CurrentDate from './CurrentDate';

function App() {
  return (
    <div className="App">
      <CurrentDate />
    </div>
  );
}

export default App;
```

This will render the current day of the week and date in the format of "Monday, January 11, 2021". The date will be updated every minute.

